def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0]); seen=set()
    for r in range(h):
      for c in range(w):
        if g[r][c]==0 or (r,c) in seen: continue
        comp=[]; stack=[(r,c)]; seen.add((r,c))
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]!=0:
              seen.add((yy,xx)); stack.append((yy,xx))
        y0=min(y for y,x in comp); y1=max(y for y,x in comp); x0=min(x for y,x in comp); x1=max(x for y,x in comp)
        layers=[]
        for d in range(min((y1-y0+1)//2+1,(x1-x0+1)//2+1)):
          samples=[g[y0+d][x] for x in range(x0+d,x1-d+1)]+[g[y][x0+d] for y in range(y0+d,y1-d+1)]
          color=next((v for v in samples if v),None)
          if color is not None and color not in layers: layers.append(color)
        if len(layers)>1:
          swap=dict(zip(layers,layers[::-1]))
          for y,x in comp: g[y][x]=swap.get(g[y][x],g[y][x])
    return g
